Repository: Know Meet (React 19 web meeting app on LiveKit). Diff base: main; head: 11ecd347 (branch feat/web-conferencing-features). This is packet 4 of 7, feature area: local meeting history (PGlite idb://). Other areas are reviewed in separate packets; do not report a defect solely because code referenced from another area is not shown.

Acceptance criteria (phase goals). Participants can: share a screen and stop; send chat to everyone or privately to one participant; blur or replace their background; pick microphone, camera and speaker with levels and preview, before and during a meeting; get an "Enable audio" prompt when autoplay is blocked. Local history (PGlite idb://) and local recordings stay on the device. Recording needs consent. Secrets stay server-side and clients get short-lived tokens. No `any` in TypeScript. Tauri calls are guarded by isTauri(). Flat UI with no borders, outlines or strokes; WCAG 2.2 AA.

Review the following unified diff:

diff --git a/apps/web/src/app/history/compose-history.ts b/apps/web/src/app/history/compose-history.ts
new file mode 100644
index 00000000..800e17d2
--- /dev/null
+++ b/apps/web/src/app/history/compose-history.ts
@@ -0,0 +1,44 @@
+// TJ-ARCH-MOB-001 compliant
+import {
+  createHistoryChangeBus,
+  createPgliteHistoryRepository,
+  openHistoryDatabase,
+  readStoragePersisted,
+  requestStoragePersistence,
+} from "../../infrastructure/history";
+import type { HistoryDatabase } from "../../infrastructure/history/history-database";
+import type { HistoryServices } from "./history-services";
+
+/**
+ * Local history over PGlite: nothing opens until the first read or write, so a tab that
+ * never joins a meeting or opens the history screen never loads the database. Composed
+ * once; a second call would start a second change bus for the same store.
+ */
+export function composeHistory(): HistoryServices {
+  // One worker client for the whole tab: the recordings index shares it (wc10).
+  let opening: Promise<HistoryDatabase> | null = null;
+  const openDatabase = (): Promise<HistoryDatabase> => {
+    if (opening === null) {
+      const attempt = openHistoryDatabase();
+      opening = attempt;
+      // A failed open is tried again on the next call.
+      attempt.catch(() => {
+        if (opening === attempt) opening = null;
+      });
+    }
+    return opening;
+  };
+  const repository = createPgliteHistoryRepository({
+    openDatabase,
+    changes: createHistoryChangeBus(),
+    isPersisted: readStoragePersisted,
+  });
+  return {
+    repository,
+    openDatabase,
+    requestPersistence: async () => {
+      await requestStoragePersistence();
+      return repository.status();
+    },
+  };
+}
