+++ b/apps/web/src/app/history/hooks/use-history-storage.ts
@@ -0,0 +1,44 @@
+// TJ-ARCH-MOB-001 compliant
+import type { HistoryStorageStatus } from "@know-meet/domain";
+import { useEntityMutation, useEntityQuery } from "@prometheus-ags/entity-graph-react";
+import {
+  HISTORY_STORAGE_ENTITY,
+  HISTORY_STORAGE_ROW_ID,
+  type HistoryStorageRow,
+} from "../../../infrastructure/entities/history-entity-types";
+import { useAppServices } from "../../app-services";
+
+export interface HistoryStorage {
+  /** Null until the first read finishes. */
+  readonly status: HistoryStorageStatus | null;
+  /**
+   * Asks the browser to keep history (`navigator.storage.persist()`); `status` follows.
+   * Call it from a click: some browsers refuse otherwise.
+   */
+  readonly requestPersistence: () => Promise<void>;
+  readonly requesting: boolean;
+}
+
+/**
+ * Whether history is kept, may be cleared by the browser, or is blocked. For the
+ * screen's notice and its "keep my history" action.
+ */
+export function useHistoryStorage(): HistoryStorage {
+  const { history } = useAppServices();
+  const query = useEntityQuery<HistoryStorageRow>(HISTORY_STORAGE_ENTITY);
+  const mutation = useEntityMutation<void, HistoryStorageRow, HistoryStorageRow>({
+    type: HISTORY_STORAGE_ENTITY,
+    mutate: async () => ({
+      id: HISTORY_STORAGE_ROW_ID,
+      status: await history.requestPersistence(),
+    }),
+    normalize: (row) => ({ id: row.id, data: row }),
+  });
+  return {
+    status: query.items[0]?.status ?? null,
+    requestPersistence: async () => {
+      await mutation.mutate();
+    },
+    requesting: mutation.state.isPending,
+  };
+}
diff --git a/apps/web/src/app/history/hooks/use-meeting-history-detail.ts b/apps/web/src/app/history/hooks/use-meeting-history-detail.ts
new file mode 100644
index 00000000..7d2f693a
--- /dev/null
+++ b/apps/web/src/app/history/hooks/use-meeting-history-detail.ts
@@ -0,0 +1,70 @@
+// TJ-ARCH-MOB-001 compliant
+import {
+  type HistoryChatMessage,
+  type MeetingHistoryId,
+  type MeetingSummary,
+  parseMeetingHistoryId,
+} from "@know-meet/domain";
+import { useEntity } from "@prometheus-ags/entity-graph-react";
+import { useEffect } from "react";
+import {
+  MEETING_DETAIL_ENTITY,
+  type MeetingDetailRow,
+} from "../../../infrastructure/entities/history-entity-types";
+import { useAppServices } from "../../app-services";
+
+export interface MeetingHistoryDetail {
+  readonly meeting: MeetingSummary | null;
+  /** Oldest first. */
+  readonly chat: readonly HistoryChatMessage[];
+  readonly loading: boolean;
+  /** True once the read finished and the meeting is not kept (deleted, or never was). */
+  readonly notFound: boolean;
+  readonly error: string | null;
+  readonly reload: () => void;
+}
+
+/**
+ * One meeting with its chat. Reads again when the meeting changes in this tab or another
+ * (chat arriving, a recording linked) and shows `notFound` once it is deleted. Pass null
+ * for no selection; nothing is read then.
+ */
+export function useMeetingHistoryDetail(id: MeetingHistoryId | null): MeetingHistoryDetail {
+  const { history } = useAppServices();
+  const repository = history.repository;
+  const result = useEntity<MeetingDetailRow, MeetingDetailRow>({
+    type: MEETING_DETAIL_ENTITY,
+    id,
+    enabled: id !== null,
+    fetch: async (meetingId) => {
+      const parsed = parseMeetingHistoryId(meetingId);
+      if (parsed === null) return { id: meetingId, meeting: null, chat: [] };
+      const read = await repository.getMeeting(parsed);
+      if (!read.ok) throw new Error(read.error.code);
+      return {
+        id: meetingId,
+        meeting: read.value?.meeting ?? null,
+        chat: read.value?.chat ?? [],
+      };
+    },
+    normalize: (row) => row,
+  });
+  const { refetch } = result;
+
+  useEffect(() => {
+    if (id === null) return undefined;
+    return repository.subscribe((change) => {
+      if (change.kind === "cleared" || change.meetingId === id) refetch();
+    });
+  }, [repository, id, refetch]);
+
+  const row = result.data;
+  return {
+    meeting: row?.meeting ?? null,
+    chat: row?.chat ?? [],
+    loading: id !== null && row === null && result.error === null,
+    notFound: row !== null && row.meeting === null,
+    error: result.error,
+    reload: refetch,
+  };
+}
diff --git a/apps/web/src/app/history/hooks/use-meeting-history-list.ts b/apps/web/src/app/history/hooks/use-meeting-history-list.ts
