+++ b/apps/web/src/app/history/new-history-id.ts
@@ -0,0 +1,13 @@
+// TJ-ARCH-MOB-001 compliant
+import { type MeetingHistoryId, parseMeetingHistoryId } from "@know-meet/domain";
+
+/**
+ * A fresh history id: a random UUID, which `parseMeetingHistoryId` accepts (36 URL-safe
+ * characters, never a room code). The throw cannot happen with a conforming
+ * `crypto.randomUUID`; it exists so the id is never null or unchecked.
+ */
+export function newMeetingHistoryId(): MeetingHistoryId {
+  const id = parseMeetingHistoryId(crypto.randomUUID());
+  if (id === null) throw new Error("crypto.randomUUID returned an unusable history id");
+  return id;
+}
diff --git a/apps/web/src/app/history/with-meeting-history.ts b/apps/web/src/app/history/with-meeting-history.ts
new file mode 100644
index 00000000..dd90a131
--- /dev/null
+++ b/apps/web/src/app/history/with-meeting-history.ts
@@ -0,0 +1,76 @@
+// TJ-ARCH-MOB-001 compliant
+import {
+  type HistoryRepository,
+  type MeetingHistoryRecorder,
+  type MeetingUseCases,
+  type RealtimeRoom,
+  type RecordingStateSource,
+  recordMeetingHistory,
+} from "@know-meet/application";
+import { newMeetingHistoryId } from "./new-history-id";
+
+export interface MeetingHistoryDependencies {
+  readonly room: RealtimeRoom;
+  readonly history: HistoryRepository;
+  /** The recording consent state; wc10 passes it so recordings are linked to the session. */
+  readonly recording?: RecordingStateSource;
+}
+
+export interface MeetingUseCasesWithHistory extends MeetingUseCases {
+  /**
+   * Ends the running history session now, as `left`, and waits for its writes. Called
+   * by `leave()`; the shell also calls it on `pagehide`, best effort.
+   */
+  endHistorySession(): Promise<void>;
+}
+
+/**
+ * Keeps this device's history of each meeting (WC-7) without the screens knowing: after
+ * `join` succeeds a recorder starts for that room, and `leave` (or the page closing)
+ * ends it. A recorder also ends itself when the room disconnects, so a lost connection
+ * is recorded as `connection-lost`. History never changes what `join` or `leave`
+ * return: a storage failure only stops history for that session.
+ */
+export function withMeetingHistory(
+  inner: MeetingUseCases,
+  dependencies: MeetingHistoryDependencies,
+): MeetingUseCasesWithHistory {
+  let current: MeetingHistoryRecorder | null = null;
+
+  const endHistorySession = async (): Promise<void> => {
+    const recorder = current;
+    current = null;
+    if (recorder !== null) await recorder.dispose();
+  };
+
+  return {
+    ...inner,
+    endHistorySession,
+    join: async (request, signal) => {
+      const result = await inner.join(request, signal);
+      if (!result.ok) return result;
+      void endHistorySession();
+      current = recordMeetingHistory(
+        {
+          room: dependencies.room,
+          history: dependencies.history,
+          newHistoryId: newMeetingHistoryId,
+          now: Date.now,
+          onStopped: (reason, detail) =>
+            // biome-ignore lint/suspicious/noConsole: WC-7 diagnostic, the only record of why history stopped
+            console.error("[know-meet] meeting history stopped", reason, detail),
+          ...(dependencies.recording === undefined ? {} : { recording: dependencies.recording }),
+        },
+        { code: result.value.code },
+      );
+      return result;
+    },
+    leave: async () => {
+      // End history when Leave is pressed, not after the room has disconnected: the end
+      // time must reach storage before the person can reload or close the tab (WC-7).
+      const ending = endHistorySession();
+      await inner.leave();
+      await ending;
+    },
+  };
+}
diff --git a/apps/web/src/infrastructure/entities/history-entity-types.ts b/apps/web/src/infrastructure/entities/history-entity-types.ts
new file mode 100644
index 00000000..a2bf5f54
--- /dev/null
+++ b/apps/web/src/infrastructure/entities/history-entity-types.ts
@@ -0,0 +1,26 @@
+// TJ-ARCH-MOB-001 compliant
+import type { HistoryChatMessage, HistoryStorageStatus, MeetingSummary } from "@know-meet/domain";
+
+/** Entity type names the history transports register under. */
+export const MEETING_SUMMARY_ENTITY = "MeetingSummary";
+export const MEETING_DETAIL_ENTITY = "MeetingDetail";
+export const HISTORY_STORAGE_ENTITY = "HistoryStorage";
+
+/** The one row of the HistoryStorage entity. */
+export const HISTORY_STORAGE_ROW_ID = "storage";
+
+/** Whether this browser keeps history, and whether it may clear it by itself. */
+export interface HistoryStorageRow {
+  readonly id: typeof HISTORY_STORAGE_ROW_ID;
+  readonly status: HistoryStorageStatus;
+}
+
+/**
+ * One meeting with its chat. `meeting` is null when the id is not kept (deleted, perhaps
+ * in another tab). Read by id through `useEntity`; there is no list of details.
+ */
+export interface MeetingDetailRow {
+  readonly id: string;
+  readonly meeting: MeetingSummary | null;
+  readonly chat: readonly HistoryChatMessage[];
+}
diff --git a/apps/web/src/infrastructure/entities/register-history-entities.ts b/apps/web/src/infrastructure/entities/register-history-entities.ts
new file mode 100644
index 00000000..2fb9db0b
--- /dev/null
+++ b/apps/web/src/infrastructure/entities/register-history-entities.ts
@@ -0,0 +1,125 @@
+// TJ-ARCH-MOB-001 compliant
+import { type HistoryRepository, toMeetingCursor } from "@know-meet/application";
+import {
+  type MeetingHistoryId,
+  type MeetingSummary,
+  parseMeetingHistoryId,
+} from "@know-meet/domain";
+import { registerEntityTransport } from "@prometheus-ags/entity-graph-core";
+import {
+  HISTORY_STORAGE_ENTITY,
+  HISTORY_STORAGE_ROW_ID,
+  type HistoryStorageRow,
+  MEETING_SUMMARY_ENTITY,
+} from "./history-entity-types";
+
+/** The history screen asks for 50 at a time (ports.ts). */
+const DEFAULT_PAGE_SIZE = 50;
+
+/** A history read failed for a reason the screen shows as an error, never as an empty list. */
+export class HistoryReadError extends Error {
+  readonly code: string;
+  constructor(code: string) {
+    super(`Local history could not be read (${code})`);
+    this.name = "HistoryReadError";
+    this.code = code;
+  }
+}
+
+/**
+ * Registers the history entity transports with the entity graph (wc09 task 9.3). Call it
+ * once at the runtime boundary.
+ *
+ * Both transports read the local store through the repository and nothing else. The
+ * repository has no filter, sort or search of its own: it pages newest first with
+ * `limit` and `cursor`, and `signal` cancels a read. The transports are `authoritative`,
+ * so any view filter or sort the screen applies runs on the rows already in the graph.
+ * Blocked storage lists as empty (the screen reads HistoryStorage for the notice); a
+ * failed read throws.
+ */
+export function registerHistoryEntities(history: HistoryRepository): void {
+  /** Ids this tab has put in the graph, so a change becomes an insert or an update. */
+  const known = new Set<string>();
+
+  registerEntityTransport<MeetingSummary>(MEETING_SUMMARY_ENTITY, {
+    identify: (meeting) => meeting.id,
+    authoritative: true,
+    list: async (query) => {
+      const cursor =
+        query.cursor === null || query.cursor === undefined
+          ? null
+          : toMeetingCursor(String(query.cursor));
+      const page = await history.listMeetings({
+        limit: query.limit ?? DEFAULT_PAGE_SIZE,
+        cursor,
+        ...(query.signal === undefined ? {} : { signal: query.signal }),
+      });
+      if (!page.ok) {
+        if (page.error.code === "history-unavailable") return { rows: [], total: 0 };
+        throw new HistoryReadError(page.error.code);
+      }
+      for (const meeting of page.value.meetings) known.add(meeting.id);
+      return {
+        rows: [...page.value.meetings],
+        total: page.value.total,
+        nextCursor: page.value.nextCursor,
+      };
+    },
+    get: async (id, signal) => {
+      const meetingId = parseMeetingHistoryId(id);
+      if (meetingId === null) return null;
+      const detail = await history.getMeeting(meetingId, signal);
+      if (!detail.ok) throw new HistoryReadError(detail.error.code);
+      return detail.value?.meeting ?? null;
+    },
+    subscribe: (onChange) => {
+      let active = true;
+      const refresh = async (id: MeetingHistoryId): Promise<void> => {
+        const detail = await history.getMeeting(id);
+        if (!active || !detail.ok) return;
+        if (detail.value === null) {
+          known.delete(id);
+          onChange({ op: "delete", id });
+          return;
+        }
+        const op = known.has(id) ? "update" : "insert";
+        known.add(id);
+        onChange({ op, id, row: detail.value.meeting });
+      };
+      const unsubscribe = history.subscribe((change) => {
+        switch (change.kind) {
+          case "meeting-changed":
+            void refresh(change.meetingId);
+            return;
+          case "meeting-deleted":
+            known.delete(change.meetingId);
+            onChange({ op: "delete", id: change.meetingId });
+            return;
+          case "cleared":
+            for (const id of known) onChange({ op: "delete", id });
+            known.clear();
+            return;
+          case "chat-appended":
+            // Always followed by meeting-changed, which carries the new message count.
+            return;
+        }
+      });
+      return () => {
+        active = false;
+        unsubscribe();
+      };
+    },
+  });
+
+  const readStorage = async (): Promise<HistoryStorageRow> => ({
+    id: HISTORY_STORAGE_ROW_ID,
+    status: await history.status(),
+  });
+
+  registerEntityTransport<HistoryStorageRow>(HISTORY_STORAGE_ENTITY, {
+    identify: (row) => row.id,
+    authoritative: true,
+    list: async () => ({ rows: [await readStorage()], total: 1 }),
+    get: async () => readStorage(),
+  });
+}
diff --git a/apps/web/src/infrastructure/history/history-change-bus.ts b/apps/web/src/infrastructure/history/history-change-bus.ts
new file mode 100644
index 00000000..05b0f6cf
--- /dev/null
+++ b/apps/web/src/infrastructure/history/history-change-bus.ts
@@ -0,0 +1,98 @@
+// TJ-ARCH-MOB-001 compliant
+import type { HistoryChange } from "@know-meet/application";
+import { type ChatMessageId, parseMeetingHistoryId, toChatMessageId } from "@know-meet/domain";
+import { HISTORY_CHANNEL_NAME } from "./history-constants";
+
+/** Fans history changes out to this tab's listeners and to every other tab of the site. */
+export interface HistoryChangeBus {
+  /** Tells this tab's listeners and other tabs. Never throws. */
+  publish(change: HistoryChange): void;
+  /** Hears changes from this tab and from other tabs. Returns the unsubscribe function. */
+  subscribe(listener: (change: HistoryChange) => void): () => void;
+}
+
+interface ChannelLike {
+  onmessage: ((event: MessageEvent<unknown>) => void) | null;
+  postMessage(message: unknown): void;
+}
+
+/** A change from another tab is outside data: rebuild it with the domain brands or drop it. */
+export function parseHistoryChange(value: unknown): HistoryChange | null {
+  if (typeof value !== "object" || value === null) return null;
+  const record = value as Record<string, unknown>;
+  if (record["kind"] === "cleared") return { kind: "cleared" };
+  const meetingId = parseMeetingHistoryId(record["meetingId"]);
+  if (meetingId === null) return null;
+  switch (record["kind"]) {
+    case "meeting-changed":
+      return { kind: "meeting-changed", meetingId };
+    case "meeting-deleted":
+      return { kind: "meeting-deleted", meetingId };
+    case "chat-appended": {
+      const ids = record["messageIds"];
+      if (!Array.isArray(ids)) return null;
+      const messageIds: ChatMessageId[] = [];
+      for (const id of ids) if (typeof id === "string") messageIds.push(toChatMessageId(id));
+      return { kind: "chat-appended", meetingId, messageIds };
+    }
+    default:
+      return null;
+  }
+}
+
+function openBroadcastChannel(): ChannelLike | null {
+  if (typeof BroadcastChannel === "undefined") return null;
+  try {
+    return new BroadcastChannel(HISTORY_CHANNEL_NAME);
+  } catch {
+    return null;
+  }
+}
+
+export function createHistoryChangeBus(
+  openChannel: () => ChannelLike | null = openBroadcastChannel,
+): HistoryChangeBus {
+  const listeners = new Set<(change: HistoryChange) => void>();
+  let channel: ChannelLike | null | undefined;
+
+  const notify = (change: HistoryChange): void => {
+    for (const listener of [...listeners]) {
+      try {
+        listener(change);
+      } catch {
+        // One failing listener must not stop the others or the write that caused this.
+      }
+    }
+  };
+
+  /** Opened on first use, so a tab that never touches history never opens a channel. */
+  const ensureChannel = (): ChannelLike | null => {
+    if (channel !== undefined) return channel;
+    channel = openChannel();
+    if (channel !== null) {
+      channel.onmessage = (event) => {
+        const change = parseHistoryChange(event.data);
+        if (change !== null) notify(change);
+      };
+    }
+    return channel;
+  };
+
+  return {
+    publish: (change) => {
+      notify(change);
+      try {
+        ensureChannel()?.postMessage(change);
+      } catch {
+        // Another tab missing one notice only delays its refresh until its next read.
+      }
+    },
+    subscribe: (listener) => {
+      listeners.add(listener);
+      ensureChannel();
+      return () => {
+        listeners.delete(listener);
+      };
+    },
+  };
+}
