@@ -0,0 +1,25 @@
+// TJ-ARCH-MOB-001 compliant
+import { type MeetingCursor, toMeetingCursor } from "@know-meet/application";
+import type { MeetingHistoryId } from "@know-meet/domain";
+
+const CURSOR_PATTERN = /^(\d{1,16}):([A-Za-z0-9_-]{16,64})$/;
+
+/** The position of the last meeting on a page: `<joinedAt>:<id>`. */
+export function cursorFor(joinedAt: number, id: MeetingHistoryId): MeetingCursor {
+  return toMeetingCursor(`${joinedAt}:${id}`);
+}
+
+export interface CursorPosition {
+  readonly joinedAt: number;
+  readonly id: string;
+}
+
+/** Null for a string this adapter did not make. */
+export function readCursor(cursor: MeetingCursor): CursorPosition | null {
+  const match = CURSOR_PATTERN.exec(cursor);
+  if (match === null) return null;
+  const joinedAt = Number(match[1]);
+  const id = match[2];
+  if (!Number.isSafeInteger(joinedAt) || id === undefined) return null;
+  return { joinedAt, id };
+}
diff --git a/apps/web/src/infrastructure/history/history-database.ts b/apps/web/src/infrastructure/history/history-database.ts
new file mode 100644
index 00000000..4950da8d
--- /dev/null
+++ b/apps/web/src/infrastructure/history/history-database.ts
@@ -0,0 +1,52 @@
+// TJ-ARCH-MOB-001 compliant
+
+/** One statement runner: the same shape for the database and for a transaction. */
+export interface SqlRunner {
+  query<T>(sql: string, params?: readonly unknown[]): Promise<{ readonly rows: T[] }>;
+}
+
+/**
+ * The slice of PGlite the history repository uses. The repository depends on this, not on
+ * PGlite, so the adapter can run against an in-memory PGlite in tests and the worker
+ * client in the browser.
+ */
+export interface HistoryDatabase extends SqlRunner {
+  transaction<T>(work: (tx: SqlRunner) => Promise<T>): Promise<T>;
+}
+
+/** The structural part of PGlite (and PGliteWorker) that `adaptPglite` needs. */
+interface PgliteLike {
+  query<T>(sql: string, params?: unknown[]): Promise<{ rows: T[] }>;
+  transaction<T>(work: (tx: PgliteLikeTransaction) => Promise<T>): Promise<T>;
+  /** Writes committed data to the IndexedDB data directory now. */
+  syncToFs(): Promise<void>;
+}
+
+interface PgliteLikeTransaction {
+  query<T>(sql: string, params?: unknown[]): Promise<{ rows: T[] }>;
+}
+
+function runner(source: PgliteLikeTransaction): SqlRunner {
+  return {
+    query: (sql, params) => source.query(sql, params === undefined ? undefined : [...params]),
+  };
+}
+
+/**
+ * Wraps a PGlite or PGliteWorker instance as a `HistoryDatabase`.
+ *
+ * PGlite 0.5.16 flushes to IndexedDB after BEGIN but not after COMMIT, so a committed
+ * transaction stays in memory until the next statement, and a reload loses it (WC-7,
+ * evidence/wc7-investigation-2026-11-20). Each transaction is therefore flushed before it
+ * resolves.
+ */
+export function adaptPglite(db: PgliteLike): HistoryDatabase {
+  return {
+    ...runner(db),
+    transaction: async (work) => {
+      const result = await db.transaction((tx) => work(runner(tx)));
+      await db.syncToFs();
+      return result;
+    },
+  };
+}
diff --git a/apps/web/src/infrastructure/history/history-rows.ts b/apps/web/src/infrastructure/history/history-rows.ts
new file mode 100644
index 00000000..ec186806
--- /dev/null
+++ b/apps/web/src/infrastructure/history/history-rows.ts
@@ -0,0 +1,163 @@
+// TJ-ARCH-MOB-001 compliant
+import {
+  type DisconnectReason,
+  type HistoryAudience,
+  type HistoryChatMessage,
+  type MeetingSummary,
+  parseChatText,
+  parseMeetingHistoryId,
+  parseRecordingRequestId,
+  parseRoomCode,
+  type RecordingRequestId,
+  type SeenParticipant,
+  toChatMessageId,
+  toParticipantIdentity,
+} from "@know-meet/domain";
+
+/** One `meeting_session` row with its aggregates, as the repository's SELECT returns it. */
+export interface SessionRow {
+  readonly id: string;
+  readonly room_code: string;
+  readonly title: string | null;
+  readonly joined_at: unknown;
+  readonly left_at: unknown;
+  readonly end_reason: string | null;
+  readonly participants: unknown;
+  readonly message_count: unknown;
+  readonly recording_ids: unknown;
+}
+
+/** One `chat_message` row. */
+export interface ChatRow {
+  readonly meeting_id: string;
+  readonly id: string;
+  readonly direction: string;
+  readonly from_identity: string;
+  readonly from_name: string;
+  readonly audience_kind: string;
+  readonly audience_to: string | null;
+  readonly audience_to_name: string | null;
+  readonly text: string;
+  readonly sent_at: unknown;
+}
+
+/** The columns every summary read selects, with the two aggregates (messageCount, recordings). */
+export const SUMMARY_SELECT = `
+  SELECT s.id, s.room_code, s.title, s.joined_at, s.left_at, s.end_reason, s.participants,
+    (SELECT count(*) FROM chat_message c WHERE c.meeting_id = s.id) AS message_count,
+    COALESCE(
+      (SELECT jsonb_agg(l.recording_id ORDER BY l.linked_at, l.recording_id)
+         FROM meeting_recording_link l WHERE l.meeting_id = s.id),
+      '[]'::jsonb) AS recording_ids
+  FROM meeting_session s`;
+
+/** bigint comes back as a number, a bigint or a string depending on size. */
+export function toNumber(value: unknown): number | null {
+  if (typeof value === "number") return Number.isFinite(value) ? value : null;
+  if (typeof value === "bigint" || typeof value === "string") {
+    const parsed = Number(value);
+    return Number.isFinite(parsed) ? parsed : null;
+  }
+  return null;
+}
+
+/** jsonb arrives parsed; a driver that returns text is handled too. */
+function jsonValue(value: unknown): unknown {
+  if (typeof value !== "string") return value;
+  try {
+    return JSON.parse(value) as unknown;
+  } catch {
+    return null;
+  }
+}
+
+function participantsOf(value: unknown): readonly SeenParticipant[] {
+  const parsed = jsonValue(value);
+  if (!Array.isArray(parsed)) return [];
+  const people: SeenParticipant[] = [];
+  for (const entry of parsed as unknown[]) {
+    if (typeof entry !== "object" || entry === null) continue;
+    const { identity, name } = entry as Record<string, unknown>;
+    if (typeof identity !== "string" || typeof name !== "string") continue;
+    people.push({ identity: toParticipantIdentity(identity), name });
+  }
+  return people;
+}
+
+function recordingIdsOf(value: unknown): readonly RecordingRequestId[] {
+  const parsed = jsonValue(value);
+  if (!Array.isArray(parsed)) return [];
+  const ids: RecordingRequestId[] = [];
+  for (const entry of parsed as unknown[]) {
+    const id = parseRecordingRequestId(entry);
+    if (id !== null) ids.push(id);
+  }
+  return ids;
+}
+
+function endReasonOf(value: string | null): DisconnectReason | null {
+  return value === "left" || value === "connection-lost" ? value : null;
+}
+
+/** Null when the row does not satisfy the domain's own rules (it was not written by this adapter). */
+export function toMeetingSummary(row: SessionRow): MeetingSummary | null {
+  const id = parseMeetingHistoryId(row.id);
+  const roomCode = parseRoomCode(row.room_code);
+  const joinedAt = toNumber(row.joined_at);
+  if (id === null || roomCode === null || joinedAt === null) return null;
+  return {
+    id,
+    roomCode,
+    title: row.title,
+    joinedAt,
+    leftAt: row.left_at === null ? null : toNumber(row.left_at),
+    endReason: endReasonOf(row.end_reason),
+    participants: participantsOf(row.participants),
+    messageCount: toNumber(row.message_count) ?? 0,
+    recordingIds: recordingIdsOf(row.recording_ids),
+  };
+}
+
+/** Null when the row does not satisfy the domain's own rules. */
+export function toHistoryChatMessageRow(row: ChatRow): HistoryChatMessage | null {
+  const meetingId = parseMeetingHistoryId(row.meeting_id);
+  const text = parseChatText(row.text);
+  const sentAt = toNumber(row.sent_at);
+  if (meetingId === null || text === null || sentAt === null) return null;
+  if (row.direction !== "sent" && row.direction !== "received") return null;
+  const audience: HistoryAudience =
+    row.audience_kind === "private" && row.audience_to !== null
+      ? {
+          kind: "private",
+          to: toParticipantIdentity(row.audience_to),
+          toName: row.audience_to_name ?? "",
+        }
+      : { kind: "everyone" };
+  return {
+    meetingId,
+    id: toChatMessageId(row.id),
+    direction: row.direction,
+    from: toParticipantIdentity(row.from_identity),
+    fromName: row.from_name,
+    audience,
+    text,
+    sentAt,
+  };
+}
+
+/** The parameters of one `INSERT INTO chat_message`, in column order. */
+export function chatInsertParams(message: HistoryChatMessage): readonly unknown[] {
+  const { audience } = message;
+  return [
+    message.meetingId,
+    message.id,
+    message.direction,
+    message.from,
+    message.fromName,
+    audience.kind,
+    audience.kind === "private" ? audience.to : null,
+    audience.kind === "private" ? audience.toName : null,
+    message.text,
+    message.sentAt,
+  ];
+}
diff --git a/apps/web/src/infrastructure/history/history-schema.ts b/apps/web/src/infrastructure/history/history-schema.ts
new file mode 100644
index 00000000..ccc849d6
--- /dev/null
+++ b/apps/web/src/infrastructure/history/history-schema.ts
@@ -0,0 +1,98 @@
+// TJ-ARCH-MOB-001 compliant
+import type { HistoryDatabase } from "./history-database";
+
+/**
+ * Local history schema (wc09 task 9.2). One migration per array entry, each a list of
+ * single statements (PGlite runs one statement per `query`). Append; never edit a
+ * released entry. A newer app in another tab may have raised the stored version: this
+ * code then leaves it alone and never downgrades.
+ *
+ * - chat_message and meeting_recording_link cascade from meeting_session, so deleting a
+ *   meeting removes its chat and links in the same statement.
+ * - meeting_recording_link has no foreign key to a recordings table on purpose: the link
+ *   is written before the wc10 recording row exists, and deleting a meeting must never
+ *   delete a recording.
+ * - Timestamps are epoch milliseconds in bigint.
+ */
+const MIGRATIONS: readonly (readonly string[])[] = [
+  [
+    `CREATE TABLE IF NOT EXISTS meeting_session (
+       id text PRIMARY KEY,
+       room_code text NOT NULL,
+       title text,
+       joined_at bigint NOT NULL,
+       left_at bigint,
+       end_reason text CHECK (end_reason IN ('left', 'connection-lost')),
+       participants jsonb NOT NULL DEFAULT '[]'::jsonb
+     )`,
+    `CREATE INDEX IF NOT EXISTS meeting_session_newest_first
+       ON meeting_session (joined_at DESC, id DESC)`,
+    `CREATE TABLE IF NOT EXISTS chat_message (
+       meeting_id text NOT NULL REFERENCES meeting_session (id) ON DELETE CASCADE,
+       id text NOT NULL,
+       direction text NOT NULL CHECK (direction IN ('sent', 'received')),
+       from_identity text NOT NULL,
+       from_name text NOT NULL,
+       audience_kind text NOT NULL CHECK (audience_kind IN ('everyone', 'private')),
+       audience_to text,
+       audience_to_name text,
+       text text NOT NULL,
+       sent_at bigint NOT NULL,
+       PRIMARY KEY (meeting_id, id)
+     )`,
+    `CREATE INDEX IF NOT EXISTS chat_message_oldest_first
+       ON chat_message (meeting_id, sent_at, id)`,
+    `CREATE TABLE IF NOT EXISTS meeting_recording_link (
+       meeting_id text NOT NULL REFERENCES meeting_session (id) ON DELETE CASCADE,
+       recording_id text NOT NULL,
+       linked_at bigint NOT NULL,
+       PRIMARY KEY (meeting_id, recording_id)
+     )`,
+  ],
+  // wc10 (10.2): the index of local recordings. The files themselves live in OPFS; this
+  // table holds what the file cannot say. `end_reason` is null while a recording is open
+  // and stays null for one that was never finalised (a closed tab): the library shows
+  // that as incomplete after checking that no tab still holds the recording's lock.
+  [
+    `CREATE TABLE IF NOT EXISTS recording (
+       id text PRIMARY KEY,
+       room_code text,
+       file_name text NOT NULL,
+       mime_type text NOT NULL,
+       started_at bigint NOT NULL,
+       ended_at bigint,
+       size_bytes bigint NOT NULL DEFAULT 0,
+       end_reason text CHECK (end_reason IN ('stopped', 'storage-full', 'failed'))
+     )`,
+    `CREATE INDEX IF NOT EXISTS recording_newest_first
+       ON recording (started_at DESC, id DESC)`,
+  ],
+];
+
+const VERSION_KEY = "schema_version";
+
+/** Brings the store to the latest schema. Idempotent; safe when several tabs call it. */
+export async function migrateHistory(db: HistoryDatabase): Promise<void> {
+  await db.transaction(async (tx) => {
+    await tx.query(
+      "CREATE TABLE IF NOT EXISTS history_meta (key text PRIMARY KEY, value text NOT NULL)",
+    );
+    const stored = await tx.query<{ value: string }>(
+      "SELECT value FROM history_meta WHERE key = $1",
+      [VERSION_KEY],
+    );
+    const before = Number(stored.rows[0]?.value ?? 0);
+    let version = Number.isFinite(before) ? before : 0;
+    for (const [index, statements] of MIGRATIONS.entries()) {
+      if (index + 1 <= version) continue;
+      for (const statement of statements) await tx.query(statement);
+      version = index + 1;
+    }
+    if (version === before) return;
+    await tx.query(
+      `INSERT INTO history_meta (key, value) VALUES ($1, $2)
+       ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value`,
+      [VERSION_KEY, String(version)],
+    );
+  });
+}
diff --git a/apps/web/src/infrastructure/history/history-worker.ts b/apps/web/src/infrastructure/history/history-worker.ts
new file mode 100644
index 00000000..11e0e5e6
--- /dev/null
+++ b/apps/web/src/infrastructure/history/history-worker.ts
@@ -0,0 +1,49 @@
+// TJ-ARCH-MOB-001 compliant
+import { PGlite } from "@electric-sql/pglite";
+import initdbWasmUrl from "@electric-sql/pglite/initdb.wasm?url";
+import pgliteDataUrl from "@electric-sql/pglite/pglite.data?url";
+import pgliteWasmUrl from "@electric-sql/pglite/pglite.wasm?url";
+import { worker } from "@electric-sql/pglite/worker";
+import { HISTORY_DATA_DIR } from "./history-constants";
+
+/**
+ * The shared history worker (wc09 task 9.2). Every tab starts one of these through
+ * `PGliteWorker`; PGlite elects a single leader across tabs, and only the leader's
+ * `init` runs, so one PGlite instance owns the `idb://` store for the whole origin.
+ *
+ * The three PGlite binaries come from Vite `?url` imports, so the build emits them as
+ * hashed same-origin assets and nothing is fetched from a CDN (connect-src stays
+ * closed). They are passed to PGlite explicitly instead of letting it resolve
+ * `new URL(..., import.meta.url)` itself.
+ */
+async function fetchOk(url: string): Promise<Response> {
+  const response = await fetch(url);
+  if (!response.ok) throw new Error(`History asset ${url} failed with ${response.status}`);
+  return response;
+}
+
+async function compileWasm(url: string): Promise<WebAssembly.Module> {
+  const response = await fetchOk(url);
+  // arrayBuffer + compile, not compileStreaming: it works whatever MIME type serves .wasm.
+  return WebAssembly.compile(await response.arrayBuffer());
+}
+
+async function fetchBlob(url: string): Promise<Blob> {
+  return (await fetchOk(url)).blob();
+}
+
+void worker({
+  init: async () => {
+    const [pgliteWasmModule, initdbWasmModule, fsBundle] = await Promise.all([
+      compileWasm(pgliteWasmUrl),
+      compileWasm(initdbWasmUrl),
+      fetchBlob(pgliteDataUrl),
+    ]);
+    return PGlite.create({
+      dataDir: HISTORY_DATA_DIR,
+      pgliteWasmModule,
+      initdbWasmModule,
+      fsBundle,
+    });
+  },
+});
