index 00000000..99da2d0c
--- /dev/null
+++ b/apps/web/src/presentation/local-history/application/history-route.ts
@@ -0,0 +1,31 @@
+// TJ-ARCH-MOB-001 compliant
+// /history sub-states in the URL hash (shape local-history.md §2): the list (no
+// hash), `#meeting:<id>` for one meeting, and "not found" for a meeting hash whose
+// id does not parse. The hash is never sent to a server and no request is keyed by
+// the id (WC-7, LH-12); the id is validated with the domain parser, never trusted raw.
+import { type MeetingHistoryId, parseMeetingHistoryId } from "@know-meet/domain";
+import { parseHashRoute } from "../../shared/use-hash-route";
+
+export type HistoryView =
+  | { readonly kind: "list" }
+  | { readonly kind: "detail"; readonly id: MeetingHistoryId }
+  | { readonly kind: "not-found" };
+
+const MEETING_VIEW = "meeting";
+
+export function resolveHistoryView(hash: string): HistoryView {
+  const route = parseHashRoute(hash);
+  if (route.view !== MEETING_VIEW) return { kind: "list" };
+  const id = parseMeetingHistoryId(route.arg);
+  return id === null ? { kind: "not-found" } : { kind: "detail", id };
+}
+
+/** Hash (without `#`) for `<Link hash>`: `meeting:<id>`. */
+export function meetingHash(id: MeetingHistoryId): string {
+  return `${MEETING_VIEW}:${id}`;
+}
+
+/** Hash (without `#`) of a recording saved in this browser, on the hosted /recordings. */
+export function recordingHash(id: string): string {
+  return `recording:${id}`;
+}
diff --git a/apps/web/src/presentation/local-history/presentation/confirm-delete-dialog.tsx b/apps/web/src/presentation/local-history/presentation/confirm-delete-dialog.tsx
new file mode 100644
index 00000000..24a41ae6
--- /dev/null
+++ b/apps/web/src/presentation/local-history/presentation/confirm-delete-dialog.tsx
@@ -0,0 +1,98 @@
+// TJ-ARCH-MOB-001 compliant
+// Shape local-history.md §6–§8, LH-7, LH-8: the kit AlertDialog for "Delete this
+// meeting?" and "Delete all history?". Focus starts on Cancel (destructive actions
+// are never the default); Escape cancels and focus returns to the opener. The
+// dialog stays open while deleting (spinner, "Deleting...") and on failure, whose
+// text sits inside the description so `aria-describedby` reads it. On success the
+// caller closes it and decides where focus goes (`returnFocus={false}`).
+import {
+  AlertDialog,
+  AlertDialogAction,
+  AlertDialogCancel,
+  AlertDialogContent,
+  AlertDialogDescription,
+  AlertDialogFooter,
+  AlertDialogHeader,
+  AlertDialogTitle,
+} from "@know-meet/ui/components/alert-dialog";
+import { KmIcon } from "@know-meet/ui/components/km-icon";
+import { Spinner } from "@know-meet/ui/components/spinner";
+import type * as React from "react";
+import { useId } from "react";
+
+export const DELETE_FAILED_TEXT = "Couldn't delete. Close other Know Meet tabs and try again.";
+
+interface ConfirmDeleteDialogProps {
+  readonly open: boolean;
+  readonly onOpenChange: (open: boolean) => void;
+  readonly title: string;
+  readonly children: React.ReactNode;
+  readonly confirmLabel: string;
+  readonly pending: boolean;
+  readonly failed: boolean;
+  /** False once the delete succeeded: the caller moves focus itself. */
+  readonly returnFocus: boolean;
+  readonly onConfirm: () => void;
+  readonly confirmTestId?: string;
+}
+
+export function ConfirmDeleteDialog({
+  open,
+  onOpenChange,
+  title,
+  children,
+  confirmLabel,
+  pending,
+  failed,
+  returnFocus,
+  onConfirm,
+  confirmTestId,
+}: ConfirmDeleteDialogProps) {
+  const cancelId = useId();
+  return (
+    <AlertDialog open={open} onOpenChange={onOpenChange}>
+      <AlertDialogContent
+        initialFocus={() => document.getElementById(cancelId)}
+        finalFocus={returnFocus}
+      >
+        <AlertDialogHeader>
+          <AlertDialogTitle>{title}</AlertDialogTitle>
+          <AlertDialogDescription render={<div />}>
+            <p className="m-0">{children}</p>
+            <p aria-live="polite" className="m-0">
+              {failed && !pending ? (
+                <span className="mt-s3 flex items-start gap-s2 font-semibold text-foreground">
+                  <KmIcon name="alert" className="mt-px size-4 text-red-text" />
+                  <span>{DELETE_FAILED_TEXT}</span>
+                </span>
+              ) : null}
+            </p>
+          </AlertDialogDescription>
+        </AlertDialogHeader>
+        <AlertDialogFooter>
+          <AlertDialogCancel id={cancelId}>Cancel</AlertDialogCancel>
+          <AlertDialogAction
+            variant="destructive"
+            disabled={pending}
+            focusableWhenDisabled
+            data-testid={confirmTestId}
+            onClick={onConfirm}
+          >
+            {pending ? (
+              <>
+                <Spinner
+                  aria-hidden="true"
+                  role="presentation"
+                  className="motion-reduce:animate-none"
+                />
+                <span>Deleting...</span>
+              </>
+            ) : (
+              confirmLabel
+            )}
+          </AlertDialogAction>
+        </AlertDialogFooter>
+      </AlertDialogContent>
+    </AlertDialog>
+  );
+}
diff --git a/apps/web/src/presentation/local-history/presentation/device-only-notice.tsx b/apps/web/src/presentation/local-history/presentation/device-only-notice.tsx
new file mode 100644
index 00000000..30ea8cb8
--- /dev/null
+++ b/apps/web/src/presentation/local-history/presentation/device-only-notice.tsx
@@ -0,0 +1,43 @@
+// TJ-ARCH-MOB-001 compliant
+// Shape local-history.md §5, §7, LH-2: the D5 notice above the list. A `section`
+// named by its heading, `surface` fill with the `shield` glyph in `fg-sub`. It holds
+// no controls; the non-persistent line appears only when the browser has not granted
+// persistent storage. Scenario contract: km-history-device-only.
+import { KmIcon } from "@know-meet/ui/components/km-icon";
+import { cn } from "@know-meet/ui/lib/utils";
+import { useId } from "react";
+
+export const DEVICE_ONLY_TEXT =
+  "History keeps the meetings you joined here and every chat message this browser received, including messages from other people. It is never uploaded or shared, and other people can't see it. Delete a meeting, or all history, at any time. Clearing this site's data in your browser also deletes it.";
+
+export const NON_PERSISTENT_TEXT =
+  "Your browser may clear this history if the device runs low on space.";
+
+export function DeviceOnlyNotice({
+  nonPersistent,
+  className,
+}: {
+  readonly nonPersistent: boolean;
+  readonly className?: string;
+}) {
+  const headingId = useId();
+  return (
+    <section
+      aria-labelledby={headingId}
+      data-testid="km-history-device-only"
+      className={cn(
+        "flex min-w-0 items-start gap-s3 rounded-base bg-surface px-s4 py-s4 text-foreground",
+        className,
+      )}
+    >
+      <KmIcon name="shield" className="mt-px shrink-0 text-muted-foreground" />
+      <div className="grid min-w-0 gap-s2">
+        <h2 id={headingId} className="m-0 text-base leading-heading font-semibold">
+          Saved only in this browser
+        </h2>
+        <p className="m-0 max-w-[72ch] text-sm text-pretty">{DEVICE_ONLY_TEXT}</p>
+        {nonPersistent ? <p className="m-0 text-sm font-semibold">{NON_PERSISTENT_TEXT}</p> : null}
+      </div>
+    </section>
+  );
+}
diff --git a/apps/web/src/presentation/local-history/presentation/history-chat.tsx b/apps/web/src/presentation/local-history/presentation/history-chat.tsx
new file mode 100644
