index 00000000..8c346837
--- /dev/null
+++ b/apps/web/src/presentation/local-history/presentation/history-day-groups.tsx
@@ -0,0 +1,127 @@
+// TJ-ARCH-MOB-001 compliant
+// Shape local-history.md §4, §8, LH-1, LH-3, LH-10: meetings grouped by day under
+// `h2` eyebrows, each meeting one `list-row` link (no nested controls) in a `ul`.
+// The link's name carries title, day and time ("Design sync, today 14:30"); the
+// visible time is a `<time datetime>`. From the medium width the message count and
+// a "Recording" marker move into trailing chips. Focus is the kit fill with the
+// inner fills dropped. Scenario contract: km-history-entry (data-history-id),
+// km-history-entry-date, km-history-entry-open.
+import type { MeetingSummary } from "@know-meet/domain";
+import { Badge } from "@know-meet/ui/components/badge";
+import {
+  Item,
+  ItemContent,
+  ItemDescription,
+  ItemMedia,
+  ItemTitle,
+} from "@know-meet/ui/components/item";
+import { KmIcon } from "@know-meet/ui/components/km-icon";
+import { cn } from "@know-meet/ui/lib/utils";
+import { Link } from "@tanstack/react-router";
+import { useId } from "react";
+import {
+  type DayGroup,
+  formatTime,
+  inlineDay,
+  isoTime,
+  meetingTitle,
+  messagesLabel,
+  rowMetaParts,
+} from "../application/history-format";
+import { meetingHash } from "../application/history-route";
+
+/** Inner fills (lead tile, chips) give way to the row's focus fill. */
+const dropFillOnFocus = "group-focus-visible/item:bg-transparent";
+
+function HistoryRow({ meeting, now }: { readonly meeting: MeetingSummary; readonly now: Date }) {
+  const parts = rowMetaParts(meeting);
+  const hasRecording = meeting.recordingIds.length > 0;
+  return (
+    <li data-testid="km-history-entry" data-history-id={meeting.id} className="min-w-0">
+      <Item
+        render={<Link to="/history" hash={meetingHash(meeting.id)} />}
+        data-testid="km-history-entry-open"
+        className="min-h-16 flex-nowrap"
+      >
+        <ItemMedia variant="icon" className={dropFillOnFocus}>
+          <KmIcon name="calendar" />
+        </ItemMedia>
+        <ItemContent>
+          <ItemTitle className="block w-full truncate">
+            {meetingTitle(meeting)}
+            <span className="sr-only">, </span>
+          </ItemTitle>
+          <ItemDescription>
+            <time data-testid="km-history-entry-date" dateTime={isoTime(meeting.joinedAt)}>
+              <span className="sr-only">{inlineDay(meeting.joinedAt, now)} </span>
+              {formatTime(meeting.joinedAt)}
+            </time>
+            {parts.map((part) => (
+              <span key={part.text} className={cn(part.chipFromMedium && "medium:hidden")}>
+                <span aria-hidden="true"> · </span>
+                <span className="sr-only">, </span>
+                {part.text}
+              </span>
+            ))}
+            {hasRecording ? (
+              <span className="medium:hidden">
+                <span aria-hidden="true"> · </span>
+                <span className="sr-only">, </span>
+                recording saved
+              </span>
+            ) : null}
+          </ItemDescription>
+        </ItemContent>
+        <span className="flex shrink-0 items-center gap-s2">
+          <Badge className={cn("max-medium:hidden", dropFillOnFocus)}>
+            <span className="sr-only">, </span>
+            {messagesLabel(meeting.messageCount)}
+          </Badge>
+          {hasRecording ? (
+            <Badge className={cn("max-medium:hidden", dropFillOnFocus)}>
+              <KmIcon name="film" />
+              <span className="sr-only">, </span>
+              Recording
+            </Badge>
+          ) : null}
+          <KmIcon name="chevron-right" className="size-4 text-muted-foreground" />
+        </span>
+      </Item>
+    </li>
+  );
+}
+
+function HistoryDayGroup({ group, now }: { readonly group: DayGroup; readonly now: Date }) {
+  const headingId = useId();
+  return (
+    <section aria-labelledby={headingId} className="grid min-w-0 gap-s3">
+      <h2
+        id={headingId}
+        className="m-0 font-mono text-sm font-semibold tracking-eyebrow text-muted-foreground uppercase"
+      >
+        {group.label}
+      </h2>
+      <ul className="m-0 grid min-w-0 list-none gap-s2 p-0">
+        {group.meetings.map((meeting) => (
+          <HistoryRow key={meeting.id} meeting={meeting} now={now} />
+        ))}
+      </ul>
+    </section>
+  );
+}
+
+export function HistoryDayGroups({
+  groups,
+  now,
+}: {
+  readonly groups: readonly DayGroup[];
+  readonly now: Date;
+}) {
+  return (
+    <div className="grid min-w-0 gap-s6">
+      {groups.map((group) => (
+        <HistoryDayGroup key={group.key} group={group} now={now} />
+      ))}
+    </div>
+  );
+}
diff --git a/apps/web/src/presentation/local-history/presentation/history-detail-view.tsx b/apps/web/src/presentation/local-history/presentation/history-detail-view.tsx
new file mode 100644
index 00000000..57819338
--- /dev/null
+++ b/apps/web/src/presentation/local-history/presentation/history-detail-view.tsx
@@ -0,0 +1,155 @@
+// TJ-ARCH-MOB-001 compliant
+// /history#meeting:<id> (shape local-history.md §2, §4, §6, LH-1, LH-4): the
+// "History" back link, the meeting title as the `h1` with date, time, duration and
+// people, then the received chat and the facts card (two columns from the expanded
+// width, one column up to 720px below it). The same `h1` element stays mounted
+// through loading, "Meeting not found" and read errors, so focus moved to it on a
+// hash change is not lost when the read finishes. The id was parsed by the route;
+// it is never put in a request (WC-7).
+import type { MeetingHistoryId, MeetingSummary } from "@know-meet/domain";
+import { buttonVariants } from "@know-meet/ui/components/button";
+import { KmIcon } from "@know-meet/ui/components/km-icon";
+import { PageHead, PageHeadText, PageSub, PageTitle } from "@know-meet/ui/components/page-head";
+import { focusFillClass } from "@know-meet/ui/lib/focus";
+import { cn } from "@know-meet/ui/lib/utils";
+import { Link } from "@tanstack/react-router";
+import type * as React from "react";
+import { useMeetingHistoryDetail } from "../../../app/history/hooks";
+import { useDocumentTitle } from "../../shared/use-document-title";
+import {
+  dayName,
+  formatDuration,
+  formatTime,
+  meetingTitle,
+  peopleLabel,
+} from "../application/history-format";
+import { HistoryChat } from "./history-chat";
+import { HistoryReadError, HistorySkeleton, StorageBlockedNote } from "./history-list-states";
+import { MeetingFactsCard } from "./meeting-facts-card";
+import { useDelayedFlag } from "./use-delayed-flag";
+
+const NOT_FOUND_TITLE = "Meeting not found";
+
+function BackLink() {
+  return (
+    <Link
+      to="/history"
+      className={cn(
+        "mb-s3 inline-flex min-h-size-target items-center gap-s2 justify-self-start rounded-base px-s2 font-semibold text-foreground no-underline hover:bg-accent",
+        focusFillClass,
+      )}
+    >
+      <KmIcon name="chevron-right" className="size-4 rotate-180" />
+      <span>History</span>
+    </Link>
+  );
+}
+
+function NotFoundBody() {
+  return (
+    <div className="grid justify-items-start gap-s4">
+      <p className="m-0 max-w-[72ch] text-muted-foreground">
+        This meeting isn't in this browser's history. It may have been deleted.
+      </p>
+      <Link to="/history" className={cn(buttonVariants(), focusFillClass)}>
+        <KmIcon name="clock" />
+        <span>Back to History</span>
+      </Link>
+    </div>
+  );
+}
+
+function meetingSub(meeting: MeetingSummary, now: Date): string {
+  const parts = [`${dayName(meeting.joinedAt, now)}, ${formatTime(meeting.joinedAt)}`];
+  const duration = formatDuration(meeting);
+  if (duration !== null) parts.push(duration);
+  parts.push(peopleLabel(meeting));
+  return parts.join(" · ");
+}
+
+interface DetailFrameProps {
+  readonly title: string;
+  readonly sub: string | null;
+  readonly children: React.ReactNode;
+}
+
+function DetailFrame({ title, sub, children }: DetailFrameProps) {
+  useDocumentTitle(`${title} — History — Know Meet`);
+  return (
+    <div className="grid min-w-0">
+      <BackLink />
+      <PageHead>
+        <PageHeadText>
+          <PageTitle className="[overflow-wrap:anywhere]">{title}</PageTitle>
+          {sub === null ? null : <PageSub>{sub}</PageSub>}
+        </PageHeadText>
+      </PageHead>
+      {children}
+    </div>
+  );
+}
+
+export function NotFoundDetailView() {
+  return (
+    <DetailFrame title={NOT_FOUND_TITLE} sub={null}>
+      <NotFoundBody />
+    </DetailFrame>
+  );
+}
+
+export function HistoryDetailView({
+  id,
+  storageBlocked,
+  onDeleted,
+}: {
+  readonly id: MeetingHistoryId;
+  readonly storageBlocked: boolean;
+  readonly onDeleted: (id: MeetingHistoryId) => void;
+}) {
+  const detail = useMeetingHistoryDetail(storageBlocked ? null : id);
+  const showSkeleton = useDelayedFlag(detail.loading);
+  const now = new Date();
+
+  if (storageBlocked) {
+    return (
+      <DetailFrame title="History unavailable" sub={null}>
+        <StorageBlockedNote />
+      </DetailFrame>
+    );
+  }
+  if (detail.error !== null) {
+    return (
+      <DetailFrame title="Meeting couldn't be read" sub={null}>
+        <HistoryReadError title="This meeting couldn't be read" onRetry={detail.reload} />
+      </DetailFrame>
+    );
+  }
+  if (detail.notFound) {
+    return (
+      <DetailFrame title={NOT_FOUND_TITLE} sub={null}>
+        <NotFoundBody />
+      </DetailFrame>
+    );
+  }
+  const meeting = detail.meeting;
+  if (meeting === null) {
+    return (
+      <DetailFrame title="Loading meeting" sub={null}>
+        <HistorySkeleton visible={showSkeleton} />
+      </DetailFrame>
+    );
+  }
+  return (
+    <DetailFrame title={meetingTitle(meeting)} sub={meetingSub(meeting, now)}>
+      <div className="grid min-w-0 max-w-[720px] gap-s6 expanded:max-w-none expanded:grid-cols-[minmax(0,2fr)_minmax(0,1fr)] expanded:items-start">
+        <HistoryChat chat={detail.chat} meeting={meeting} />
+        <MeetingFactsCard
+          meeting={meeting}
+          messageCount={detail.chat.length}
+          now={now}
+          onDeleted={() => onDeleted(meeting.id)}
+        />
+      </div>
+    </DetailFrame>
+  );
+}
diff --git a/apps/web/src/presentation/local-history/presentation/history-list-states.tsx b/apps/web/src/presentation/local-history/presentation/history-list-states.tsx
new file mode 100644
index 00000000..83089a46
--- /dev/null
+++ b/apps/web/src/presentation/local-history/presentation/history-list-states.tsx
@@ -0,0 +1,137 @@
+// TJ-ARCH-MOB-001 compliant
+// Shape local-history.md §6 states for the list area: loading skeletons (LH-6,
+// no shimmer), the empty region ("No meetings on this device yet"), storage
+// unavailable (LH-9: static content with an `alert` glyph and a heading, not
+// role="alert") and a read failure (cause, then the fix).
+import { Button, buttonVariants } from "@know-meet/ui/components/button";
+import {
+  Empty,
+  EmptyContent,
+  EmptyDescription,
+  EmptyHeader,
+  EmptyMedia,
+  EmptyTitle,
+} from "@know-meet/ui/components/empty";
+import { KmIcon } from "@know-meet/ui/components/km-icon";
+import { focusFillClass } from "@know-meet/ui/lib/focus";
+import { cn } from "@know-meet/ui/lib/utils";
+import { Link } from "@tanstack/react-router";
+import type * as React from "react";
+import { useEffect, useId, useRef } from "react";
+
+const SKELETON_ROWS = ["a", "b", "c"] as const;
+
+/** Three `muted` rows after the 300 ms delay; the list region carries `aria-busy`. */
+export function HistorySkeleton({ visible }: { readonly visible: boolean }) {
+  return (
+    <section aria-busy="true" aria-label="Loading history" className="grid gap-s2">
+      {visible
+        ? SKELETON_ROWS.map((key) => (
+            <div key={key} aria-hidden="true" className="h-16 rounded-base bg-muted" />
+          ))
+        : null}
+    </section>
+  );
+}
+
+/**
+ * The empty state. `focusHeading` moves focus to its heading once it shows, after
+ * "Delete all history" (shape §6).
+ */
+export function EmptyHistory({ focusHeading }: { readonly focusHeading: boolean }) {
+  const headingId = useId();
+  const heading = useRef<HTMLHeadingElement>(null);
+  useEffect(() => {
+    if (focusHeading) heading.current?.focus({ preventScroll: true });
+  }, [focusHeading]);
+  return (
+    <Empty role="region" aria-labelledby={headingId}>
+      <EmptyHeader>
+        <EmptyMedia variant="icon">
+          <KmIcon name="clock" />
+        </EmptyMedia>
+        <EmptyTitle
+          render={(props) => (
+            <h2
+              {...props}
+              id={headingId}
+              ref={heading}
+              tabIndex={-1}
+              className={cn(props.className, "outline-none")}
+            />
+          )}
+        >
+          No meetings on this device yet
+        </EmptyTitle>
+        <EmptyDescription>
+          Meetings you join in this browser appear here with the chat you received. Nothing is
+          uploaded.
+        </EmptyDescription>
+      </EmptyHeader>
+      <EmptyContent>
+        <Link to="/" className={cn(buttonVariants(), focusFillClass)}>
+          <KmIcon name="cam" />
+          <span>Start a meeting</span>
+        </Link>
+      </EmptyContent>
+    </Empty>
+  );
+}
+
+/** `red-soft` note with the `alert` glyph in `red-text`; no controls sit on its fill. */
+function ErrorNote({
+  title,
+  children,
+}: {
+  readonly title: string;
+  readonly children: React.ReactNode;
+}) {
+  const headingId = useId();
+  return (
+    <section
+      aria-labelledby={headingId}
+      className="flex min-w-0 items-start gap-s3 rounded-base bg-red-soft px-s4 py-s4 text-foreground"
+    >
+      <KmIcon name="alert" className="mt-px shrink-0 text-red-text" />
+      <div className="grid min-w-0 gap-s2">
+        <h2 id={headingId} className="m-0 text-base leading-heading font-semibold">
+          {title}
+        </h2>
+        <p className="m-0 text-sm text-pretty">{children}</p>
+      </div>
+    </section>
+  );
+}
+
+/** IndexedDB blocked (some private windows): no list and no delete controls. */
+export function StorageBlockedNote() {
+  return (
+    <ErrorNote title="History isn't available in this window">
+      This browser blocked local storage, which happens in some private windows. Meetings still
+      work, but nothing is saved here.
+    </ErrorNote>
+  );
+}
+
+/** Reading history failed for another reason; reading again may succeed. */
+export function HistoryReadError({
+  title,
+  onRetry,
+}: {
+  readonly title: string;
+  readonly onRetry: () => void;
+}) {
+  return (
+    <div className="grid gap-s3">
+      <ErrorNote title={title}>
+        This browser couldn't read its saved history. Close other Know Meet tabs, then try again.
+      </ErrorNote>
+      <div>
+        <Button variant="secondary" onClick={onRetry}>
+          <KmIcon name="refresh" />
+          <span>Try again</span>
+        </Button>
+      </div>
+    </div>
+  );
+}
diff --git a/apps/web/src/presentation/local-history/presentation/history-list-view.tsx b/apps/web/src/presentation/local-history/presentation/history-list-view.tsx
new file mode 100644
index 00000000..b45c06f1
--- /dev/null
+++ b/apps/web/src/presentation/local-history/presentation/history-list-view.tsx
@@ -0,0 +1,156 @@
+// TJ-ARCH-MOB-001 compliant
+// /history list (shape local-history.md §2, §4, §6, LH-4): page head ("On this
+// device" / "History"), the D5 notice with "Delete all history" (one row from the
+// expanded width), then the list area by state: storage blocked, loading, read
+// error, empty, or day groups with "Show 50 more". Delete all confirms first; on
+// success the empty state takes focus and a toast confirms.
+import type { HistoryStorageStatus } from "@know-meet/domain";
+import { Button } from "@know-meet/ui/components/button";
+import { KmIcon } from "@know-meet/ui/components/km-icon";
+import { PageEyebrow, PageHead, PageHeadText, PageTitle } from "@know-meet/ui/components/page-head";
+import { Spinner } from "@know-meet/ui/components/spinner";
+import { toast } from "@know-meet/ui/components/toast";
+import { useState } from "react";
+import { type MeetingHistoryList, useDeleteAllMeetingHistory } from "../../../app/history/hooks";
+import { useDocumentTitle } from "../../shared/use-document-title";
+import { groupByDay } from "../application/history-format";
+import { ConfirmDeleteDialog } from "./confirm-delete-dialog";
+import { DeviceOnlyNotice } from "./device-only-notice";
+import { HistoryDayGroups } from "./history-day-groups";
+import {
+  EmptyHistory,
+  HistoryReadError,
+  HistorySkeleton,
+  StorageBlockedNote,
+} from "./history-list-states";
+import { useDelayedFlag } from "./use-delayed-flag";
+
+function DeleteAllControl({ onCleared }: { readonly onCleared: () => void }) {
+  const { deleteAll, pending } = useDeleteAllMeetingHistory();
+  const [open, setOpen] = useState(false);
+  const [failed, setFailed] = useState(false);
+  const [cleared, setCleared] = useState(false);
+
+  const confirm = async () => {
+    setFailed(false);
+    const ok = await deleteAll();
+    if (!ok) {
+      setFailed(true);
+      return;
+    }
+    setCleared(true);
+    setOpen(false);
+    onCleared();
+    toast.add({ title: "History deleted from this browser." });
+  };
+
+  return (
+    <>
+      <Button
+        variant="ghost"
+        className="justify-self-start expanded:justify-self-end"
+        onClick={() => {
+          setFailed(false);
+          setCleared(false);
+          setOpen(true);
+        }}
+      >
+        <KmIcon name="trash" />
+        <span>Delete all history</span>
+      </Button>
+      <ConfirmDeleteDialog
+        open={open}
+        onOpenChange={(next) => {
+          if (!pending) setOpen(next);
+        }}
+        title="Delete all history?"
+        confirmLabel="Delete all history"
+        pending={pending}
+        failed={failed}
+        returnFocus={!cleared}
+        onConfirm={() => void confirm()}
+      >
+        Every meeting and chat message saved in this browser is removed. Recordings are kept in
+        Recordings. This can't be undone.
+      </ConfirmDeleteDialog>
+    </>
+  );
+}
+
+function ListArea({
+  list,
+  storage,
+  focusEmpty,
+}: {
+  readonly list: MeetingHistoryList;
+  readonly storage: HistoryStorageStatus | null;
+  readonly focusEmpty: boolean;
+}) {
+  const waiting = storage === null || list.loading;
+  const showSkeleton = useDelayedFlag(waiting);
+  if (storage === "blocked") return <StorageBlockedNote />;
+  if (waiting) return <HistorySkeleton visible={showSkeleton} />;
+  if (list.error !== null) {
+    return <HistoryReadError title="History couldn't be read" onRetry={list.reload} />;
+  }
+  if (list.meetings.length === 0) return <EmptyHistory focusHeading={focusEmpty} />;
+  const now = new Date();
+  return (
+    <div className="grid min-w-0 gap-s5">
+      <HistoryDayGroups groups={groupByDay(list.meetings, now)} now={now} />
+      {list.hasMore ? (
+        <div>
+          <Button
+            variant="secondary"
+            disabled={list.loadingMore}
+            focusableWhenDisabled
+            onClick={list.loadMore}
+          >
+            {list.loadingMore ? (
+              <>
+                <Spinner
+                  aria-hidden="true"
+                  role="presentation"
+                  className="motion-reduce:animate-none"
+                />
+                <span>Loading...</span>
+              </>
+            ) : (
+              "Show 50 more"
+            )}
+          </Button>
+        </div>
+      ) : null}
+    </div>
+  );
+}
+
+export function HistoryListView({
+  list,
+  storage,
+}: {
+  readonly list: MeetingHistoryList;
+  readonly storage: HistoryStorageStatus | null;
+}) {
+  const [focusEmpty, setFocusEmpty] = useState(false);
+  useDocumentTitle("History — Know Meet");
+  const canDeleteAll =
+    storage !== null && storage !== "blocked" && !list.loading && list.meetings.length > 0;
+  return (
+    <>
+      <PageHead>
+        <PageHeadText>
+          <PageEyebrow>On this device</PageEyebrow>
+          <PageTitle>History</PageTitle>
+        </PageHeadText>
+      </PageHead>
+      <div className="grid min-w-0 gap-s5">
+        <div className="grid min-w-0 gap-s3 expanded:grid-cols-[minmax(0,1fr)_auto] expanded:items-start expanded:gap-s4">
+          <DeviceOnlyNotice nonPersistent={storage === "non-persistent"} />
+          {canDeleteAll ? <DeleteAllControl onCleared={() => setFocusEmpty(true)} /> : null}
+        </div>
+        <ListArea list={list} storage={storage} focusEmpty={focusEmpty} />
+      </div>
+    </>
+  );
+}
diff --git a/apps/web/src/presentation/local-history/presentation/history-screen.tsx b/apps/web/src/presentation/local-history/presentation/history-screen.tsx
new file mode 100644
index 00000000..c0b83bf0
--- /dev/null
+++ b/apps/web/src/presentation/local-history/presentation/history-screen.tsx
@@ -0,0 +1,92 @@
+// TJ-ARCH-MOB-001 compliant
+// /history (wc09 task 9.4, shape docs/design/shapes/web-conferencing/local-history.md):
+// meetings and the chat this browser received, kept only on this device (D5, no
+// backfill D3). The list is the route itself; one meeting opens at
+// `/history#meeting:<id>` through client navigation only, so the local id never
+// reaches a request (WC-7, LH-12). The root keeps the scenario contract id
+// `km-screen-history` (tests/release/src/wc-test-ids.ts).
+//
+// Focus on a hash change: into the detail, the `h1`; back to the list (back link or
+// browser Back), the row that was opened; after deleting a meeting, the row that
+// followed it, or the `h1` when none did (shape §6, §8).
+import type { MeetingHistoryId } from "@know-meet/domain";
+import { Toaster, toast } from "@know-meet/ui/components/toast";
+import { useLocation, useNavigate } from "@tanstack/react-router";
+import { useEffect, useRef } from "react";
+import { useHistoryStorage, useMeetingHistoryList } from "../../../app/history/hooks";
+import { ScreenPage } from "../../shared/screen-page";
+import { resolveHistoryView } from "../application/history-route";
+import { HistoryDetailView, NotFoundDetailView } from "./history-detail-view";
+import { HistoryListView } from "./history-list-view";
+
+function focusPageHeading(): void {
+  const heading = document.querySelector<HTMLElement>("main h1");
+  if (heading === null) return;
+  if (!heading.hasAttribute("tabindex")) heading.setAttribute("tabindex", "-1");
+  heading.focus({ preventScroll: true });
+}
+
+/** Focuses the row link of a meeting in the list; false when that row is not shown. */
+function focusRow(id: MeetingHistoryId): boolean {
+  const link = document.querySelector<HTMLElement>(
+    `[data-history-id="${CSS.escape(id)}"] [data-testid="km-history-entry-open"]`,
+  );
+  if (link === null) return false;
+  link.focus();
+  return true;
+}
+
+export function HistoryScreen() {
+  const hash = useLocation({ select: (location) => location.hash });
+  const navigate = useNavigate();
+  const view = resolveHistoryView(hash);
+  const list = useMeetingHistoryList();
+  const storage = useHistoryStorage();
+  /** The row to focus when the list shows again: the one opened, or the one after a deleted one. */
+  const returnRow = useRef<MeetingHistoryId | null>(null);
+  const previousHash = useRef(hash);
+
+  useEffect(() => {
+    if (previousHash.current === hash) return; // first render, or no change
+    previousHash.current = hash;
+    const current = resolveHistoryView(hash);
+    if (current.kind === "detail") returnRow.current = current.id;
+    if (current.kind !== "list") {
+      window.scrollTo(0, 0);
+      focusPageHeading();
+      return;
+    }
+    const row = returnRow.current;
+    returnRow.current = null;
+    if (row === null || !focusRow(row)) {
+      window.scrollTo(0, 0);
+      focusPageHeading();
+    }
+  }, [hash]);
+
+  const onDeleted = (id: MeetingHistoryId) => {
+    const index = list.meetings.findIndex((meeting) => meeting.id === id);
+    returnRow.current = index === -1 ? null : (list.meetings[index + 1]?.id ?? null);
+    toast.add({ title: "Meeting deleted from this browser." });
+    void navigate({ to: "/history", replace: true });
+  };
+
+  return (
+    <Toaster>
+      <ScreenPage data-testid="km-screen-history">
+        {view.kind === "list" ? (
+          <HistoryListView list={list} storage={storage.status} />
+        ) : view.kind === "detail" ? (
+          <HistoryDetailView
+            key={view.id}
+            id={view.id}
+            storageBlocked={storage.status === "blocked"}
+            onDeleted={onDeleted}
+          />
+        ) : (
+          <NotFoundDetailView />
+        )}
+      </ScreenPage>
+    </Toaster>
+  );
+}
