--- /dev/null
+++ b/apps/web/src/presentation/local-history/presentation/use-delayed-flag.ts
@@ -0,0 +1,20 @@
+// TJ-ARCH-MOB-001 compliant
+// Shape local-history.md §6 "Loading": the list area shows nothing for 300 ms, then
+// skeleton rows, so a fast local read never flashes a placeholder.
+import { useEffect, useState } from "react";
+
+export const SKELETON_DELAY_MS = 300;
+
+/** True once `active` has stayed true for `delayMs`; false again as soon as it is not. */
+export function useDelayedFlag(active: boolean, delayMs: number = SKELETON_DELAY_MS): boolean {
+  const [elapsed, setElapsed] = useState(false);
+  useEffect(() => {
+    if (!active) return undefined;
+    const timer = window.setTimeout(() => setElapsed(true), delayMs);
+    return () => {
+      window.clearTimeout(timer);
+      setElapsed(false);
+    };
+  }, [active, delayMs]);
+  return active && elapsed;
+}
diff --git a/packages/application/src/history/ports.ts b/packages/application/src/history/ports.ts
new file mode 100644
index 00000000..a6ea205d
--- /dev/null
+++ b/packages/application/src/history/ports.ts
@@ -0,0 +1,142 @@
+import type {
+  ChatMessageId,
+  HistoryChatMessage,
+  HistoryEntryNotFound,
+  HistoryStorageError,
+  HistoryStorageStatus,
+  MeetingHistoryId,
+  MeetingSession,
+  MeetingSummary,
+  RecordingRequestId,
+  Result,
+} from "@know-meet/domain";
+
+/**
+ * Opaque position in the meeting list. Only the repository that returned it can read it;
+ * pass it back unchanged to get the next page.
+ */
+export type MeetingCursor = string & { readonly __brand: "MeetingCursor" };
+
+/** Marks a repository-made string as a cursor. Only repository adapters call it. */
+export function toMeetingCursor(value: string): MeetingCursor {
+  return value as MeetingCursor;
+}
+
+export interface MeetingListQuery {
+  /** Page size, at least 1. The history screen asks for 50 at a time. */
+  readonly limit: number;
+  /** Null for the first page. */
+  readonly cursor: MeetingCursor | null;
+  readonly signal?: AbortSignal;
+}
+
+export interface MeetingPage {
+  /** Newest first: by `joinedAt` descending, then `id` descending. */
+  readonly meetings: readonly MeetingSummary[];
+  /** Null when this page is the last. */
+  readonly nextCursor: MeetingCursor | null;
+  /** Every meeting kept in this browser, across all pages. */
+  readonly total: number;
+}
+
+/** One meeting with every chat message kept for it, oldest first (`sentAt`, then id). */
+export interface MeetingDetail {
+  readonly meeting: MeetingSummary;
+  readonly chat: readonly HistoryChatMessage[];
+}
+
+/**
+ * What changed in the store, from this tab or any other tab of the same site. Listeners
+ * re-read what they show; the change carries ids only, never history text.
+ *
+ * - `meeting-changed`: created or updated, including its message count or recordings.
+ * - `chat-appended`: new messages were kept for a meeting (it is also `meeting-changed`).
+ */
+export type HistoryChange =
+  | { readonly kind: "meeting-changed"; readonly meetingId: MeetingHistoryId }
+  | {
+      readonly kind: "chat-appended";
+      readonly meetingId: MeetingHistoryId;
+      readonly messageIds: readonly ChatMessageId[];
+    }
+  | { readonly kind: "meeting-deleted"; readonly meetingId: MeetingHistoryId }
+  | { readonly kind: "cleared" };
+
+/** HistoryEntryNotFound: the meeting was deleted (perhaps in another tab) or never kept. */
+export type HistoryWriteError = HistoryStorageError | HistoryEntryNotFound;
+
+/**
+ * This browser's history of meetings and the chat it received (WC-7, decisions D1, D3,
+ * D5). The web adapter (wc09 task 9.2) keeps it in PGlite on `idb://` behind a
+ * leader-elected worker; entity transports read it and nothing else.
+ *
+ * - Local only. No method sends anything over the network, and an adapter must not
+ *   either: not to a server, not to other participants (no chat backfill, D3).
+ * - Expected failures are results, never throws. When `status()` is `blocked`, every other
+ *   method returns HistoryUnavailable and `subscribe` never fires.
+ * - A fired `signal` rejects the promise with the signal's reason (an AbortError), the
+ *   standard abort behaviour entity transports rely on; abort is not a storage failure.
+ * - Every write is idempotent, so a retry after an uncertain outcome is safe.
+ * - After a write resolves, a read in any tab sees it, and `subscribe` listeners in every
+ *   tab are told.
+ * - Recordings are a separate store (wc10). History only refers to them by id; no delete
+ *   here ever removes a recording.
+ */
+export interface HistoryRepository {
+  /** Whether this browser can keep history and whether it may clear it by itself. */
+  status(): Promise<HistoryStorageStatus>;
+
+  listMeetings(query: MeetingListQuery): Promise<Result<MeetingPage, HistoryStorageError>>;
+
+  /** The meeting and its chat, or null when it is not kept (deleted or unknown id). */
+  getMeeting(
+    id: MeetingHistoryId,
+    signal?: AbortSignal,
+  ): Promise<Result<MeetingDetail | null, HistoryStorageError>>;
+
+  /**
+   * Keeps a new session as given (session start). Creating an id that already exists
+   * changes nothing and succeeds.
+   */
+  createMeeting(session: MeetingSession): Promise<Result<void, HistoryStorageError>>;
+
+  /**
+   * Replaces a kept session's title, `leftAt`, `endReason` and participants (people seen,
+   * session end); `roomCode` and `joinedAt` never change. A deleted session is not
+   * recreated: HistoryEntryNotFound.
+   */
+  updateMeeting(session: MeetingSession): Promise<Result<void, HistoryWriteError>>;
+
+  /**
+   * Keeps chat messages for a session, all or none. Messages whose (meetingId, id) is
+   * already kept are skipped, so appending the same message twice keeps it once. Every
+   * message's `meetingId` must equal `meetingId`. HistoryEntryNotFound when the session
+   * is not kept.
+   */
+  appendChat(
+    meetingId: MeetingHistoryId,
+    messages: readonly HistoryChatMessage[],
+  ): Promise<Result<void, HistoryWriteError>>;
+
+  /**
+   * Records that a local recording was made during the session, so its row shows the
+   * recording and the detail links to it. Linking twice keeps one link. The recording
+   * itself is not touched and need not exist yet.
+   */
+  linkRecording(
+    meetingId: MeetingHistoryId,
+    recordingId: RecordingRequestId,
+  ): Promise<Result<void, HistoryWriteError>>;
+
+  /**
+   * Removes the session, its chat and its recording links, permanently. Recordings stay
+   * in the recordings store. Deleting an id that is not kept succeeds.
+   */
+  deleteMeeting(id: MeetingHistoryId): Promise<Result<void, HistoryStorageError>>;
+
+  /** Removes every session, message and link. Recordings stay. */
+  deleteAll(): Promise<Result<void, HistoryStorageError>>;
+
+  /** Tells the listener about every change from now on. Returns the unsubscribe function. */
+  subscribe(listener: (change: HistoryChange) => void): () => void;
+}
diff --git a/packages/application/src/history/record-meeting-history.ts b/packages/application/src/history/record-meeting-history.ts
new file mode 100644
index 00000000..912cb343
--- /dev/null
+++ b/packages/application/src/history/record-meeting-history.ts
@@ -0,0 +1,234 @@
+import {
+  type ChatMessageId,
+  endMeetingSession,
+  type HistoryError,
+  isInRoom,
+  type MeetingHistoryId,
+  type MeetingSession,
+  type ParticipantIdentity,
+  type RecordingConsentState,
+  type RecordingRequestId,
+  type Result,
+  type RoomCode,
+  type SeenParticipant,
+  seenName,
+  startMeetingSession,
+  toHistoryChatMessage,
+  withParticipantsSeen,
+} from "@know-meet/domain";
+import type { RealtimeRoom, RoomSnapshot } from "../meeting/ports.ts";
+import type { HistoryRepository } from "./ports.ts";
+
+/** The recording consent state, read like the room. `RecordingConsent` satisfies it. */
+export interface RecordingStateSource {
+  getSnapshot(): RecordingConsentState;
+  subscribe(listener: () => void): () => void;
+}
+
+export interface MeetingHistoryPorts {
+  readonly room: RealtimeRoom;
+  readonly history: HistoryRepository;
+  /**
+   * A fresh history id per session, for example `crypto.randomUUID()` checked with
+   * `parseMeetingHistoryId`. Never the room code.
+   */
+  readonly newHistoryId: () => MeetingHistoryId;
+  /** Milliseconds since the Unix epoch. */
+  readonly now: () => number;
+  /**
+   * When given, each recording this browser makes during the session is linked to it once
+   * the recorder is running (`local-recording`); a request that never started is not.
+   */
+  readonly recording?: RecordingStateSource;
+  /**
+   * Told once when history stops for this session, with the error code or the thrown
+   * error's name. A stop is otherwise silent (history never interrupts the meeting), so
+   * this is the only record of why a later message is missing.
+   */
+  readonly onStopped?: (reason: "unavailable" | "failed" | "deleted", detail: string) => void;
+}
+
+/** The meeting being joined. */
+export interface MeetingToRecord {
+  readonly code: RoomCode;
+  /** The room's display name; omitted or null when it has none. */
+  readonly title?: string | null;
+}
+
+/**
+ * - `waiting`: not in the room yet; nothing is kept until the room is joined.
+ * - `recording`: the session is kept and updated as people and messages arrive.
+ * - `ended`: the room was left; the session's end is (being) written.
+ * - `stopped`: history stopped for this session and writes nothing more. `unavailable`:
+ *   the browser blocks storage. `failed`: a write failed. `deleted`: the session was
+ *   deleted while it ran (perhaps in another tab), and is not recreated.
+ */
+export type MeetingHistoryRecorderState =
+  | { readonly status: "waiting" }
+  | { readonly status: "recording"; readonly meetingId: MeetingHistoryId }
+  | { readonly status: "ended"; readonly meetingId: MeetingHistoryId }
+  | {
+      readonly status: "stopped";
+      readonly reason: "unavailable" | "failed" | "deleted";
+      readonly meetingId: MeetingHistoryId;
+    };
+
+export interface MeetingHistoryRecorder {
+  getState(): MeetingHistoryRecorderState;
+  /** Resolves once every write so far has finished. */
+  settled(): Promise<void>;
+  /** Stops listening; a running session is ended as `left` first. */
+  dispose(): Promise<void>;
+}
+
+/**
+ * Keeps one meeting session in this device's history (WC-7): created when the room is
+ * joined, updated with the people seen, every chat message this device sends or receives
+ * while present, and local recordings made, and ended when the room is left. History
+ * never waits on the meeting and the meeting never waits on history: a storage failure
+ * only stops recording history.
+ *
+ * Chat is read from the room snapshot's append-only `chat`: only the entries past the
+ * length last seen are new. The list starts empty again on a new `connect`, so a shorter
+ * list (or a different first message) starts over from the beginning, and every message
+ * is written at most once by id. The repository also skips ids it already has.
+ *
+ * Writes run one at a time, in order, so a session is always created before its chat and
+ * ended after it. Create one recorder per join, right after `join` succeeds.
+ */
+export function recordMeetingHistory(
+  ports: MeetingHistoryPorts,
+  meeting: MeetingToRecord,
+): MeetingHistoryRecorder {
+  const { room, history } = ports;
+  let state: MeetingHistoryRecorderState = { status: "waiting" };
+  let session: MeetingSession | null = null;
+  let chatSeen = 0;
+  let firstChatId: ChatMessageId | null = null;
+  const kept = new Set<ChatMessageId>();
+  const linked = new Set<RecordingRequestId>();
+  let chain: Promise<void> = Promise.resolve();
+  const unsubscribers: Array<() => void> = [];
+
+  const unsubscribeAll = (): void => {
+    for (const unsubscribe of unsubscribers.splice(0)) unsubscribe();
+  };
+
+  const stop = (reason: "unavailable" | "failed" | "deleted", detail: string): void => {
+    if (state.status === "waiting" || state.status === "stopped") return;
+    state = { status: "stopped", reason, meetingId: state.meetingId };
+    unsubscribeAll();
+    ports.onStopped?.(reason, detail);
+  };
+
+  const stopFor = (error: HistoryError): void => {
+    if (error.code === "history-unavailable") stop("unavailable", error.code);
+    else if (error.code === "history-entry-not-found") stop("deleted", error.code);
+    else stop("failed", error.code);
+  };
+
+  /** Queues one write. Once stopped, queued writes are skipped. A throw counts as failed. */
+  const write = (operation: () => Promise<Result<void, HistoryError>>): void => {
+    chain = chain.then(async () => {
+      if (state.status === "stopped") return;
+      try {
+        const result = await operation();
+        if (!result.ok) stopFor(result.error);
+      } catch (error) {
+        stop("failed", error instanceof Error ? `${error.name}: ${error.message}` : "thrown");
+      }
+    });
+  };
+
+  const begin = (snapshot: RoomSnapshot): MeetingSession => {
+    const started = startMeetingSession({
+      id: ports.newHistoryId(),
+      roomCode: meeting.code,
+      title: meeting.title ?? null,
+      joinedAt: ports.now(),
+      participants: participantsIn(snapshot),
+    });
+    session = started;
+    state = { status: "recording", meetingId: started.id };
+    write(() => history.createMeeting(started));
+    return started;
+  };
+
+  const noteParticipants = (current: MeetingSession, snapshot: RoomSnapshot): MeetingSession => {
+    const next = withParticipantsSeen(current, participantsIn(snapshot));
+    if (next === current) return current;
+    session = next;
+    write(() => history.updateMeeting(next));
+    return next;
+  };
+
+  const noteChat = (current: MeetingSession, snapshot: RoomSnapshot): void => {
+    const chat = snapshot.chat;
+    const restarted = chat.length < chatSeen || (chatSeen > 0 && chat[0]?.id !== firstChatId);
+    const from = restarted ? 0 : chatSeen;
+    chatSeen = chat.length;
+    firstChatId = chat[0]?.id ?? null;
+    const fresh = chat.slice(from).filter((message) => !kept.has(message.id));
+    if (fresh.length === 0) return;
+    for (const message of fresh) kept.add(message.id);
+    const nameOf = (identity: ParticipantIdentity) => seenName(current, identity);
+    const records = fresh.map((message) => toHistoryChatMessage(current.id, message, nameOf));
+    write(() => history.appendChat(current.id, records));
+  };
+
+  const end = (current: MeetingSession, reason: "left" | "connection-lost"): void => {
+    const ended = endMeetingSession(current, ports.now(), reason);
+    session = ended;
+    state = { status: "ended", meetingId: ended.id };
+    unsubscribeAll();
+    write(() => history.updateMeeting(ended));
+  };
+
+  const onRoomChange = (): void => {
+    const snapshot = room.getSnapshot();
+    if (state.status === "waiting") {
+      if (!isInRoom(snapshot.connection)) return;
+      begin(snapshot);
+    }
+    if (state.status !== "recording" || session === null) return;
+    const current = noteParticipants(session, snapshot);
+    noteChat(current, snapshot);
+    if (snapshot.connection.status === "disconnected") end(current, snapshot.connection.reason);
+  };
+
+  const onRecordingChange = (): void => {
+    if (state.status !== "recording" || ports.recording === undefined) return;
+    const recording = ports.recording.getSnapshot();
+    if (recording.status !== "local-recording" || linked.has(recording.requestId)) return;
+    linked.add(recording.requestId);
+    const meetingId = state.meetingId;
+    const recordingId = recording.requestId;
+    write(() => history.linkRecording(meetingId, recordingId));
+  };
+
+  unsubscribers.push(room.subscribe(onRoomChange));
+  if (ports.recording !== undefined)
+    unsubscribers.push(ports.recording.subscribe(onRecordingChange));
+  onRoomChange();
+  onRecordingChange();
+
+  return {
+    getState: () => state,
+    settled: () => chain,
+    dispose: async () => {
+      if (state.status === "recording" && session !== null) end(session, "left");
+      unsubscribeAll();
+      await chain;
+    },
+  };
+}
+
+/** This participant first, then remote participants in join order. */
+function participantsIn(snapshot: RoomSnapshot): readonly SeenParticipant[] {
+  const remotes = snapshot.remotes.map((remote) => ({
+    identity: remote.identity,
+    name: remote.displayName,
+  }));
+  if (snapshot.local === null) return remotes;
+  return [{ identity: snapshot.local.identity, name: snapshot.local.displayName }, ...remotes];
+}
diff --git a/packages/domain/src/history/history-chat-message.ts b/packages/domain/src/history/history-chat-message.ts
new file mode 100644
index 00000000..549a2c30
--- /dev/null
+++ b/packages/domain/src/history/history-chat-message.ts
@@ -0,0 +1,77 @@
+import type { ChatMessage, ChatMessageId, ChatText } from "../conferencing/chat-message.ts";
+import type { ParticipantIdentity } from "../meeting/participant.ts";
+import type { MeetingHistoryId } from "./meeting-history-id.ts";
+
+/**
+ * Who a kept message was for. A private message keeps the recipient's name as it was in
+ * the meeting, because the history screen labels it after everyone has left.
+ */
+export type HistoryAudience =
+  | { readonly kind: "everyone" }
+  | {
+      readonly kind: "private";
+      readonly to: ParticipantIdentity;
+      /** Empty when this device never saw the recipient's name. */
+      readonly toName: string;
+    };
+
+/**
+ * One chat message this device sent or received during a meeting session, kept locally
+ * (decision D5: other people's messages included, never uploaded). Only messages received
+ * while present exist here: there is no backfill from anyone (decision D3).
+ */
+export interface HistoryChatMessage {
+  readonly meetingId: MeetingHistoryId;
+  /** Unique within the session; the store keeps one row per (meetingId, id). */
+  readonly id: ChatMessageId;
+  readonly direction: "sent" | "received";
+  readonly from: ParticipantIdentity;
+  readonly fromName: string;
+  readonly audience: HistoryAudience;
+  /** Plain text. History never turns it into links (shape decision 3). */
+  readonly text: ChatText;
+  /** Milliseconds since the Unix epoch, as the transport stamped it. */
+  readonly sentAt: number;
+}
+
+/**
+ * The label the history screen shows for a message's audience, without the copy: the
+ * presentation turns it into "Everyone", "Private to Marcus" or "Private from Marcus",
+ * the same labels the room's chat panel uses (wc04).
+ */
+export type AudienceLabel =
+  | { readonly kind: "everyone" }
+  | { readonly kind: "private-to"; readonly name: string }
+  | { readonly kind: "private-from"; readonly name: string };
+
+/**
+ * Turns a room chat message into the record history keeps. `nameOf` resolves the
+ * recipient of a private message; a received private message is always addressed to this
+ * device, so its recipient is this participant.
+ */
+export function toHistoryChatMessage(
+  meetingId: MeetingHistoryId,
+  message: ChatMessage,
+  nameOf: (identity: ParticipantIdentity) => string | null,
+): HistoryChatMessage {
+  const audience: HistoryAudience =
+    message.audience.kind === "everyone"
+      ? { kind: "everyone" }
+      : { kind: "private", to: message.audience.to, toName: nameOf(message.audience.to) ?? "" };
+  return {
+    meetingId,
+    id: message.id,
+    direction: message.direction,
+    from: message.from,
+    fromName: message.fromName,
+    audience,
+    text: message.text,
+    sentAt: message.sentAt,
+  };
+}
+
+export function audienceLabel(message: HistoryChatMessage): AudienceLabel {
+  if (message.audience.kind === "everyone") return { kind: "everyone" };
+  if (message.direction === "sent") return { kind: "private-to", name: message.audience.toName };
+  return { kind: "private-from", name: message.fromName };
+}
diff --git a/packages/domain/src/history/history-error.ts b/packages/domain/src/history/history-error.ts
new file mode 100644
index 00000000..90a3104d
--- /dev/null
+++ b/packages/domain/src/history/history-error.ts
@@ -0,0 +1,39 @@
+/**
+ * Whether this browser can keep history, as the history screen reports it.
+ *
+ * - `persistent`: stored, and the browser granted persistent storage.
+ * - `non-persistent`: stored, but the browser may clear it under storage pressure
+ *   (`navigator.storage.persisted()` is false); the notice says so.
+ * - `blocked`: nothing can be stored, for example IndexedDB refused in a private window.
+ *   Meetings still work; nothing is saved.
+ */
+export type HistoryStorageStatus = "persistent" | "non-persistent" | "blocked";
+
+/** The browser refused local storage (status `blocked`). Nothing was read or written. */
+export interface HistoryUnavailable {
+  readonly code: "history-unavailable";
+}
+
+/**
+ * The store was there but the operation did not complete: quota exceeded, the storage
+ * worker crashed, or another tab held the store too long. Nothing partial was kept.
+ */
+export interface HistoryStorageFailed {
+  readonly code: "history-storage-failed";
+}
+
+/** The meeting session is not in this browser's history: deleted, or never kept. */
+export interface HistoryEntryNotFound {
+  readonly code: "history-entry-not-found";
+}
+
+/** Failures every history operation can have. */
+export type HistoryStorageError = HistoryUnavailable | HistoryStorageFailed;
+
+export type HistoryError = HistoryStorageError | HistoryEntryNotFound;
+
+export const historyErrors = {
+  unavailable: (): HistoryUnavailable => ({ code: "history-unavailable" }),
+  storageFailed: (): HistoryStorageFailed => ({ code: "history-storage-failed" }),
+  entryNotFound: (): HistoryEntryNotFound => ({ code: "history-entry-not-found" }),
+} as const;
diff --git a/packages/domain/src/history/meeting-history-id.ts b/packages/domain/src/history/meeting-history-id.ts
new file mode 100644
index 00000000..9b47840c
--- /dev/null
+++ b/packages/domain/src/history/meeting-history-id.ts
@@ -0,0 +1,25 @@
+import { parseRoomCode } from "../meeting/room-code.ts";
+
+/**
+ * Identifies one meeting session in this device's local history. It is generated on the
+ * device when the session starts and never derived from the room code: the same room can
+ * be joined many times, and the code is shared with everyone who had the link, while
+ * history ids must stay unguessable and local (WC-7 forbids them in any request).
+ */
+export type MeetingHistoryId = string & { readonly __brand: "MeetingHistoryId" };
+
+/** Shortest accepted id. A room code (`km-xxx-xxx`, 10 characters) is always shorter. */
+export const MIN_MEETING_HISTORY_ID_LENGTH = 16;
+
+const HISTORY_ID_PATTERN = /^[A-Za-z0-9_-]{16,64}$/;
+
+/**
+ * Accepts 16 to 64 URL-safe characters (a UUID fits) that are not a room code. Use it for
+ * every id that arrives from outside the history store, for example the `#meeting:<id>`
+ * hash; returns null for anything else.
+ */
+export function parseMeetingHistoryId(value: unknown): MeetingHistoryId | null {
+  if (typeof value !== "string" || !HISTORY_ID_PATTERN.test(value)) return null;
+  if (parseRoomCode(value) !== null) return null;
+  return value as MeetingHistoryId;
+}
diff --git a/packages/domain/src/history/meeting-session.ts b/packages/domain/src/history/meeting-session.ts
new file mode 100644
index 00000000..aff69915
--- /dev/null
+++ b/packages/domain/src/history/meeting-session.ts
@@ -0,0 +1,101 @@
+import type { RecordingRequestId } from "../conferencing/recording-consent.ts";
+import type { DisconnectReason } from "../meeting/connection-state.ts";
+import type { ParticipantIdentity } from "../meeting/participant.ts";
+import type { RoomCode } from "../meeting/room-code.ts";
+import type { MeetingHistoryId } from "./meeting-history-id.ts";
+
+/** Someone this device saw in the room, with the latest display name it saw for them. */
+export interface SeenParticipant {
+  readonly identity: ParticipantIdentity;
+  readonly name: string;
+}
+
+/**
+ * One meeting as this device took part in it: from joining to leaving one room once.
+ * Joining the same room again is a new session with a new id. It lives only in this
+ * browser and is never uploaded (decision D5).
+ */
+export interface MeetingSession {
+  readonly id: MeetingHistoryId;
+  /** The room joined. Data only: it is never the session's id. */
+  readonly roomCode: RoomCode;
+  /**
+   * The room's display name, or null when none was set (guest rooms today). Presentation
+   * shows "Meeting <code>" for null.
+   */
+  readonly title: string | null;
+  /** Milliseconds since the Unix epoch, when this device was first in the room. */
+  readonly joinedAt: number;
+  /**
+   * When this device left, or null while the meeting runs. It also stays null when the
+   * tab closed before leaving was recorded; such a session has no known duration.
+   */
+  readonly leftAt: number | null;
+  /** Why it ended; null while it runs or when the end was never recorded. */
+  readonly endReason: DisconnectReason | null;
+  /** Everyone seen in the room, this participant first, then in the order first seen. */
+  readonly participants: readonly SeenParticipant[];
+}
+
+/**
+ * A session as the history list shows it: with how many chat messages this device kept
+ * and which local recordings were made during it. Recordings belong to the recordings
+ * store (wc10); history only refers to them, and deleting a session never deletes one.
+ */
+export interface MeetingSummary extends MeetingSession {
+  readonly messageCount: number;
+  readonly recordingIds: readonly RecordingRequestId[];
+}
+
+export interface MeetingSessionStart {
+  readonly id: MeetingHistoryId;
+  readonly roomCode: RoomCode;
+  readonly title: string | null;
+  readonly joinedAt: number;
+  readonly participants: readonly SeenParticipant[];
+}
+
+export function startMeetingSession(start: MeetingSessionStart): MeetingSession {
+  return { ...start, leftAt: null, endReason: null };
+}
+
+/**
+ * Adds participants not seen before and takes the latest name of known ones. Returns the
+ * same object when nothing changed, so a caller can skip the write.
+ */
+export function withParticipantsSeen(
+  session: MeetingSession,
+  seen: readonly SeenParticipant[],
+): MeetingSession {
+  const byIdentity = new Map(session.participants.map((p) => [p.identity, p] as const));
+  let changed = false;
+  for (const person of seen) {
+    const known = byIdentity.get(person.identity);
+    if (known !== undefined && known.name === person.name) continue;
+    byIdentity.set(person.identity, person);
+    changed = true;
+  }
+  if (!changed) return session;
+  return { ...session, participants: [...byIdentity.values()] };
+}
+
+/** Marks the session ended. An already ended session is returned unchanged. */
+export function endMeetingSession(
+  session: MeetingSession,
+  leftAt: number,
+  reason: DisconnectReason,
+): MeetingSession {
+  if (session.leftAt !== null) return session;
+  return { ...session, leftAt, endReason: reason };
+}
+
+/** Length in milliseconds, or null while running or when the end was never recorded. */
+export function meetingDurationMs(session: MeetingSession): number | null {
+  if (session.leftAt === null) return null;
+  return Math.max(0, session.leftAt - session.joinedAt);
+}
+
+/** The latest name this session saw for an identity, or null if it never saw them. */
+export function seenName(session: MeetingSession, identity: ParticipantIdentity): string | null {
+  return session.participants.find((p) => p.identity === identity)?.name ?? null;
+}
